const rawData = $input.first().json.data;
const parsedData = JSON.parse(rawData);

const contactId = parsedData.id;
const contactName = parsedData.name;
const responsibleUserId = parsedData.responsible_user_id;

// Extrair telefone
const phone = parsedData.custom_fields_values?.find(
  field => field.field_code === 'PHONE'
)?.values?.[0]?.value || null;

// Extrair todos os leads
const leads = parsedData._embedded?.leads || [];

// Pipeline alvo (do Edit Fields)
const targetPipelineId = parseInt($('normatização-dados').first().json.pipelineid);

// Buscar lead no pipeline alvo
const leadInTargetPipeline = leads.find(
  lead => lead.pipeline_id === targetPipelineId
);

// Buscar lead em outro pipeline (primeiro encontrado)
const leadInOtherPipeline = leads.find(
  lead => lead.pipeline_id !== targetPipelineId
);

// Determinar cenário
let scenario = '';
if (leads.length === 0) {
  scenario = 'no_leads'; // Criar lead novo
} else if (leadInTargetPipeline) {
  scenario = 'lead_in_target_pipeline'; // Atualizar lead existente
} else if (leadInOtherPipeline) {
  scenario = 'lead_in_other_pipeline'; // Criar lead duplicado
}

return {
  json: {
    // Dados do contato
    contact_id: contactId,
    contact_name: contactName,
    contact_phone: phone,
    responsible_user_id: responsibleUserId,

    // Cenário identificado
    scenario: scenario,

    // Flags booleanas (para usar no Switch)
    has_no_leads: leads.length === 0,
    has_lead_in_target_pipeline: !!leadInTargetPipeline,
    has_lead_in_other_pipeline: !!leadInOtherPipeline && !leadInTargetPipeline,

    // Dados do lead no pipeline alvo (se existir)
    lead_id_in_target: leadInTargetPipeline?.id || null,
    lead_status_in_target: leadInTargetPipeline?.status_id || null,
    lead_name_in_target: leadInTargetPipeline?.name || null,

    // Dados do lead em outro pipeline (se existir)
    lead_id_in_other: leadInOtherPipeline?.id || null,
    other_pipeline_id: leadInOtherPipeline?.pipeline_id || null,
    lead_status_in_other: leadInOtherPipeline?.status_id || null,

    // Metadata
    total_leads: leads.length,
    target_pipeline_id: targetPipelineId,
    all_pipeline_ids: leads.map(lead => lead.pipeline_id)
  }
};

const rawData = $input.first().json.data;
const parsedData = JSON.parse(rawData);

// Dados principais do lead
const leadId = parsedData.id;
const leadName = parsedData.name;
const leadPrice = parsedData.price;
const responsibleUserId = parsedData.responsible_user_id;
const statusId = parsedData.status_id;
const pipelineId = parsedData.pipeline_id;
const lossReasonId = parsedData.loss_reason_id;

// Timestamps
const createdAt = parsedData.created_at;
const updatedAt = parsedData.updated_at;
const closedAt = parsedData.closed_at;
const closestTaskAt = parsedData.closest_task_at;

// Flags
const isDeleted = parsedData.is_deleted;
const score = parsedData.score;
const laborCost = parsedData.labor_cost;

// Extrair campo customizado (IA) Link da conversa
const linkConversa = parsedData.custom_fields_values?.find(
  field => field.field_id === 1111066
)?.values?.[0]?.value || null;

// Extrair tags
const tags = parsedData._embedded?.tags || [];
const companies = parsedData._embedded?.companies || [];

// Pipeline alvo (do Edit Fields)
const targetPipelineId = parseInt($('normatização-dados').first().json.pipelineid);
const targetStatusId = parseInt($('normatização-dados').first().json.statusid);

// Verificar se está no pipeline e status corretos
const isInTargetPipeline = pipelineId === targetPipelineId;
const isInTargetStatus = statusId === targetStatusId;
const needsUpdate = !isInTargetStatus;

return {
  json: {
    // IDs principais
    lead_id: leadId,
    lead_name: leadName,
    pipeline_id: pipelineId,
    status_id: statusId,
    responsible_user_id: responsibleUserId,

    // Dados financeiros
    price: leadPrice,
    labor_cost: laborCost,
    loss_reason_id: lossReasonId,

    // Timestamps
    created_at: createdAt,
    updated_at: updatedAt,
    closed_at: closedAt,
    closest_task_at: closestTaskAt,

    // Flags
    is_deleted: isDeleted,
    score: score,

    // Campos customizados
    ia_link_conversa: linkConversa,

    // Relacionamentos
    tags: tags,
    companies: companies,
    has_tags: tags.length > 0,
    has_companies: companies.length > 0,

    // Análise de estado
    target_pipeline_id: targetPipelineId,
    target_status_id: targetStatusId,
    is_in_target_pipeline: isInTargetPipeline,
    is_in_target_status: isInTargetStatus,
    needs_update: needsUpdate,

    // Cenário
    scenario: isInTargetPipeline && isInTargetStatus 
      ? 'already_correct' 
      : 'needs_update'
  }
};

// Pegar apenas o primeiro item do array
